import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))
    s = int(next(iterator))

    leaf_count = 0
    degree = [0] * (n + 1)

    for _ in range(n - 1):
        u = int(next(iterator))
        v = int(next(iterator))
        degree[u] += 1
        degree[v] += 1

    for i in range(1, n + 1):
        if degree[i] == 1:
            leaf_count += 1

    if leaf_count == 0:
        # Should not happen for n >= 2 in a tree, but handled for safety
        result = float(s)
    else:
        result = float(s) / (leaf_count / 2)

    print(f"{result:.20f}")

if __name__ == "__main__":
    main()
